package pe.com.dentalamericana.admin;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="configuracion_sistema")public class SystemSetting{@Id private String clave;@Column(nullable=false,length=500)private String valor;@Column(nullable=false,length=250)private String descripcion;@Column(name="actualizado_por")private Long updatedBy;@Column(name="actualizado_en",nullable=false)private Instant updatedAt;@Version private Long version;protected SystemSetting(){}public void update(String value,Long actor){valor=value;updatedBy=actor;}@PrePersist void create(){updatedAt=Instant.now();}@PreUpdate void touch(){updatedAt=Instant.now();}public String getKey(){return clave;}public String getValue(){return valor;}public String getDescription(){return descripcion;}public Long getUpdatedBy(){return updatedBy;}public Instant getUpdatedAt(){return updatedAt;}public Long getVersion(){return version;}}
